import { LightningElement, api } from 'lwc';

/** Illustrations for the Release Relay guide, picked by name. */
export default class OrgToGitGuideArt extends LightningElement {
    @api name;

    get is_overview() { return this.name === 'overview'; }
    get is_connect() { return this.name === 'connect'; }
    get is_select() { return this.name === 'select'; }
    get is_review() { return this.name === 'review'; }
    get is_raise() { return this.name === 'raise'; }
    get is_track() { return this.name === 'track'; }
    get is_branchflow() { return this.name === 'branchflow'; }
    get is_route() { return this.name === 'route'; }
    get is_repo() { return this.name === 'repo'; }
    get is_env() { return this.name === 'env'; }
    get is_form() { return this.name === 'form'; }
    get is_sequence() { return this.name === 'sequence'; }
    get is_pr() { return this.name === 'pr'; }
}
